/* Motion tokens · Designed using Design Lounge (https://www.designlounge.live) */
:root {
  --ease-standard: cubic-bezier(0.2, 0.7, 0.2, 1);
  --ease-expo-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-ios-sheet: cubic-bezier(0.32, 0.72, 0, 1);
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);
  --ease-emphasized: cubic-bezier(0.2, 0, 0, 1);
  --ease-emphasized-decel: cubic-bezier(0.05, 0.7, 0.1, 1);
  --ease-emphasized-accel: cubic-bezier(0.3, 0, 0.8, 0.15);
  --ease-spring-soft: cubic-bezier(0.22, 1.2, 0.36, 1);
  --ease-spring-snappy: cubic-bezier(0.34, 1.4, 0.64, 1);
  --ease-linear: linear;
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --t-micro: 120ms;
  --t-fast: 160ms;
  --t-ui: 200ms;
  --t-layout: 320ms;
  --t-sheet: 400ms;
  --t-hero: 640ms;
  --t-cinematic: 900ms;
}
